# Scheduling script for the given CSP

from datetime import datetime, timedelta

# Helper functions
def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    h = m // 60
    mm = m % 60
    return f"{h:02d}:{mm:02d}"

def complement(work_start: int, work_end: int, busy):
    """Return list of free intervals within work hours given busy intervals (list of (s,e) in minutes)."""
    free = []
    cur = work_start
    for s, e in sorted(busy):
        if cur < s:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def intersect_intervals(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        start = max(s1, s2)
        end = min(e1, e2)
        if start < end:
            res.append((start, end))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return res

# Data definition
days = ["Monday", "Tuesday", "Wednesday"]
work_start = to_min("09:00")
work_end = to_min("17:00")
duration = 30  # minutes

# Busy schedules (day -> list of (start,end) strings)
nancy_busy = {
    "Monday":    [("10:00","10:30"), ("11:30","12:30"), ("13:30","14:00"), ("14:30","15:30"), ("16:00","17:00")],
    "Tuesday":   [("09:30","10:30"), ("11:00","11:30"), ("12:00","12:30"), ("13:00","13:30"), ("15:30","16:00")],
    "Wednesday": [("10:00","11:30"), ("13:30","16:00")]
}
jose_busy = {
    "Monday":    [("09:00","17:00")],
    "Tuesday":   [("09:00","17:00")],
    "Wednesday": [("09:00","09:30"), ("10:00","12:30"), ("13:30","14:30"), ("15:00","17:00")]
}

# Convert busy schedules to minutes
def convert(schedule):
    return {d: [(to_min(s), to_min(e)) for s, e in intervals] for d, intervals in schedule.items()}

nancy_busy_min = convert(nancy_busy)
jose_busy_min = convert(jose_busy)

# Compute free intervals for each participant per day
def free_per_day(busy_min):
    free = {}
    for d in days:
        busy = busy_min.get(d, [])
        free[d] = complement(work_start, work_end, busy)
    return free

nancy_free = free_per_day(nancy_busy_min)
jose_free = free_per_day(jose_busy_min)

# Find earliest common slot
answer = None
for d in days:
    common = intersect_intervals(nancy_free[d], jose_free[d])
    for s, e in common:
        if e - s >= duration:
            start = s
            end = s + duration
            answer = [d, to_str(start), to_str(end)]
            break
    if answer:
        break

print(answer)

