import datetime

# Helper functions
def to_minutes(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_time_str(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def subtract_intervals(base, busy):
    """Subtract busy intervals from a base interval list.
    base, busy: list of (start, end) minutes, sorted, non‑overlapping.
    Returns list of free intervals."""
    free = []
    for b_start, b_end in base:
        cur = b_start
        for s, e in busy:
            if e <= cur or s >= b_end:
                continue
            if s > cur:
                free.append((cur, s))
            cur = max(cur, e)
            if cur >= b_end:
                break
        if cur < b_end:
            free.append((cur, b_end))
    return free

def intersect_intervals(list1, list2):
    """Intersect two interval lists."""
    i, j = 0, 0
    res = []
    while i < len(list1) and j < len(list2):
        a_start, a_end = list1[i]
        b_start, b_end = list2[j]
        start = max(a_start, b_start)
        end = min(a_end, b_end)
        if start < end:
            res.append((start, end))
        if a_end <= b_end:
            i += 1
        else:
            j += 1
    return res

