    "Amy": {
        "Wednesday": [("11:00", "11:30"), ("13:30", "14:00")]
    },
    "Pamela": {
        "Monday": [("09:00", "10:30"), ("11:00", "16:30")],
        "Tuesday": [("09:00", "09:30"), ("10:00", "17:00")],
        "Wednesday": [("09:00", "09:30"), ("10:00", "11:00"),
                      ("11:30", "13:30"), ("14:30", "15:00"),
                      ("16:00", "16:30")]
    }
}

# Preference penalties
def penalty(day, start_min):
    pen = 0
    if day in ("Monday", "Tuesday"):
        pen += 1
    if day == "Wednesday" and start_min < to_minutes("16:00"):
        pen += 1
    return pen

days = ["Monday", "Tuesday", "Wednesday"]
best = None  # (penalty, start_min, day, end_min)

