def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    h = m // 60
    mn = m % 60
    return f"{h:02d}:{mn:02d}"

def subtract_interval(avails, busy):
    result = []
    b_start, b_end = busy
    for a_start, a_end in avails:
        if b_end <= a_start or b_start >= a_end:
            # no overlap
            result.append((a_start, a_end))
        else:
            # overlap exists, cut out
            if b_start > a_start:
                result.append((a_start, b_start))
            if b_end < a_end:
                result.append((b_end, a_end))
    return result

def intersect_intervals(a, b):
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

# Data
