        "Tuesday": [("09:00","10:30"),("11:00","13:00"),("13:30","14:00"),("14:30","15:30"),("16:00","16:30")]
    }
}

# Additional personal constraints
# Amanda does not want to meet on Tuesday after 11:00 -> limit end <= 11:00
# Nathan cannot meet on Monday -> remove Monday entirely
personal_constraints = {
    "Amanda": {
        "Tuesday": ("09:00","11:00")  # allowed window
    },
    "Nathan": {
        "Monday": None  # not allowed
    }
}

