from datetime import datetime, timedelta

# Helper functions to convert between "HH:MM" strings and minutes since midnight
def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def complement(intervals, work_start, work_end):
    """Return free intervals within work hours given busy intervals (sorted, non‑overlapping)."""
    free = []
    prev_end = work_start
    for s, e in intervals:
        if s > prev_end:
            free.append((prev_end, s))
        prev_end = max(prev_end, e)
    if prev_end < work_end:
        free.append((prev_end, work_end))
    return free

def intersect(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

