import sys

# Helper functions
def to_min(t: str) -> int:
    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_str(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

# Data
days_order = ['Monday', 'Tuesday', 'Wednesday', 'Thursday']
work_start = to_min('09:00')
work_end = to_min('17:00')
duration = 30  # minutes

# Busy intervals for James (in minutes)
james_busy = {
    'Monday':    [('09:00', '09:30'), ('10:30', '11:00'), ('12:30', '13:00'), ('14:30', '15:30'), ('16:30', '17:00')],
    'Tuesday':   [('09:00', '11:00'), ('11:30', '12:00'), ('12:30', '15:30'), ('16:00', '17:00')],
    'Wednesday': [('10:00', '11:00'), ('12:00', '13:00'), ('13:30', '16:00')],
    'Thursday':  [('09:30', '11:30'), ('12:00', '12:30'), ('13:00', '13:30'), ('14:00', '14:30'), ('16:30', '17:00')],
}
for d in james_busy:
    james_busy[d] = [(to_min(s), to_min(e)) for s, e in james_busy[d]]

# Cheryl's preferences: avoid Wednesday and Thursday if possible
avoid = {'Wednesday', 'Thursday'}

def free_intervals(busy):
    """Given a sorted list of busy (start, end) minutes, return list of free intervals within work hours."""
    free = []
    cur = work_start
    for s, e in sorted(busy):
        if cur < s:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def find_meeting():
    # First try days not avoided, then avoided days
    for pass_avoid in (False, True):
        for day in days_order:
            if (day in avoid) != pass_avoid:
                continue
            busy = james_busy.get(day, [])
            free = free_intervals(busy)
            for s, e in free:
                if e - s >= duration:
                    start = s
                    end = start + duration
                    return [day, to_str(start), to_str(end)]
    return None

result = find_meeting()
if result is None:
    sys.exit(1)
print(result)
